content.content:
}
.sidebar-toggle {
  flex: none;
  padding: 2px 7px;
  font-size: 12px;
  line-height: 1.4;
}

.sidebar-group,
.sidebar-foot {
  display: grid;
  gap: 2px;
}
.sidebar-foot {
  margin-top: auto;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}
.sidebar-heading {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--fg-muted);
  margin: 0 0 4px;
  padding: 0 8px;
}

.sidebar-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 7px 8px;
  border: 0;
  border-radius: 7px;
  background: none;
  color: var(--fg-muted);
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
}
.sidebar-item:hover {
  color: var(--fg);
  background: rgba(255, 255, 255, 0.05);
  text-decoration: none;
}
