button {
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  color: var(--fg);
  background: #1c1c25;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  padding: 8px 14px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, opacity 0.15s;
}
